import { router } from '@inertiajs/react';
import type { ReactNode } from 'react';
import { useTranslation } from 'react-i18next';
import { PageHeader } from '@/components/layout/page-header';
import { buttonVariants } from '@/components/ui/button';
import {
    Pagination,
    PaginationContent,
    PaginationItem,
} from '@/components/ui/pagination';
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from '@/components/ui/select';
import { useScrollRegion } from '@/hooks/use-scroll-region';
import { LIST_PER_PAGE_OPTIONS, listUrlWithPerPage } from '@/lib/list-per-page';
import { cn } from '@/lib/utils';

export type PageLayoutProps = {
    description?: ReactNode;
    subheader?: ReactNode;
    filters?: ReactNode;
    filtersRight?: ReactNode;
    children: ReactNode;
    footer?: ReactNode;
    className?: string;
    scrollContent?: boolean;
};

/**
 * Standard admin page scaffold with optional header, scrollable body, and footer.
 *
 * When a page enters multi-select mode, callers should pass `filtersRight={null}`
 * (or omit it) so only bulk actions remain visible in the toolbar row.
 *
 * @param {PageLayoutProps} props - Layout section props.
 * @returns {JSX.Element}
 */
export function PageLayout({
    description,
    subheader,
    filters,
    filtersRight,
    children,
    footer,
    className,
    scrollContent = false,
}: PageLayoutProps) {
    const showHeader = Boolean(
        description || subheader || filters || filtersRight,
    );

    return (
        <div
            className={cn('flex min-h-0 flex-1 flex-col gap-4 p-4', className)}
        >
            {showHeader ? (
                <PageHeader
                    description={description}
                    subheader={subheader}
                    filters={filters}
                    filtersRight={filtersRight}
                />
            ) : null}

            <div
                className={cn(
                    'flex min-h-0 flex-1 flex-col',
                    scrollContent ? 'overflow-y-auto' : null,
                )}
            >
                {children}
            </div>

            {footer ? (
                <div className="flex shrink-0 justify-center">{footer}</div>
            ) : null}
        </div>
    );
}

/**
 * Flat wrapper for data tables with optional sticky footer: no card surface,
 * the table sits straight on the framed content panel (like the file grid),
 * so lists don't read as a box inside a box. Spacing and row separators come
 * from Table*.
 * The panel is the scroll container: the Table wrapper's own overflow is
 * released so the header row sticks to the top of the panel while rows scroll
 * (the bottom rule is an inset shadow because collapsed borders scroll away).
 *
 * @param {{ children: ReactNode, className?: string, footer?: ReactNode }} props - Panel props.
 * @param {ReactNode} props.children - Table or list content.
 * @param {string} [props.className] - Additional panel classes.
 * @param {ReactNode} [props.footer] - Optional footer (e.g. pagination).
 * @returns {JSX.Element}
 */
export function TablePanel({
    children,
    className,
    footer,
}: {
    children: ReactNode;
    className?: string;
    footer?: ReactNode;
}) {
    const [setScrollRegion, scrollRegionTabIndex] =
        useScrollRegion<HTMLDivElement>();

    return (
        <div
            className={cn(
                'flex min-h-0 flex-1 flex-col overflow-hidden',
                className,
            )}
        >
            <div
                ref={setScrollRegion}
                tabIndex={scrollRegionTabIndex}
                data-slot="table-panel-scroll"
                className="min-h-0 flex-1 overflow-auto outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset [&_[data-slot=table-container]]:overflow-visible [&_thead]:sticky [&_thead]:top-0 [&_thead]:z-10 [&_thead]:bg-background [&_thead_th]:shadow-[inset_0_-1px_0_var(--color-border)] [&_thead_tr]:border-b-0"
            >
                {children}
            </div>
            {footer ? (
                <div className="flex shrink-0 justify-center border-t px-2 pt-3">
                    {footer}
                </div>
            ) : null}
        </div>
    );
}

export type TablePaginationLink = {
    url: string | null;
    label: string;
    active: boolean;
};

/**
 * Strip Laravel pagination HTML labels to plain text for aria / layout checks.
 */
function paginationPlainLabel(label: string): string {
    // Parse as HTML so tags/entities resolve safely — regex tag-stripping
    // reintroduces nested sequences (CodeQL js/incomplete-multi-character-sanitization).
    return (
        new DOMParser()
            .parseFromString(label, 'text/html')
            .body.textContent?.replace(/\s+/g, ' ')
            .trim() ?? ''
    );
}

/**
 * @param {string} label - Raw Laravel pagination link label (may include HTML entities).
 * @returns {string | undefined} Accessible name for the control.
 */
function paginationAriaLabel(label: string): string | undefined {
    const plain = paginationPlainLabel(label);

    if (/^\d+$/.test(plain)) {
        return `Go to page ${plain}`;
    }

    if (/previous/i.test(plain)) {
        return 'Go to previous page';
    }

    if (/next/i.test(plain)) {
        return 'Go to next page';
    }

    return plain.length > 0 ? plain : undefined;
}

/**
 * Laravel-style pagination link row via shadcn Pagination + Inertia visits.
 * Query params are unchanged; controls remain `<button>` for browser tests.
 *
 * @param {{ links: TablePaginationLink[] }} props - Component props.
 * @param {TablePaginationLink[]} props.links - Pagination links from the server.
 * @returns {JSX.Element | null}
 */
export function TablePagination({
    links,
    className,
}: {
    links: TablePaginationLink[];
    className?: string;
}) {
    if (links.length === 0) {
        return null;
    }

    return (
        <Pagination className={className}>
            <PaginationContent>
                {links.map((link, index) => {
                    const plain = paginationPlainLabel(link.label);
                    const isPageNumber = /^\d+$/.test(plain);

                    return (
                        <PaginationItem key={index}>
                            <button
                                type="button"
                                className={cn(
                                    buttonVariants({
                                        variant: link.active
                                            ? 'outline'
                                            : 'ghost',
                                        size: isPageNumber ? 'icon' : 'default',
                                    }),
                                    !isPageNumber && 'min-w-0 px-2.5',
                                    !link.url &&
                                        'pointer-events-none opacity-50',
                                )}
                                disabled={!link.url}
                                aria-label={paginationAriaLabel(link.label)}
                                aria-current={link.active ? 'page' : undefined}
                                onClick={() =>
                                    link.url && router.visit(link.url)
                                }
                                dangerouslySetInnerHTML={{
                                    __html: link.label,
                                }}
                            />
                        </PaginationItem>
                    );
                })}
            </PaginationContent>
        </Pagination>
    );
}

/** Paginator slice the list footer needs (flat `Paginated` shape). */
export type TablePaginationState = {
    current_page: number;
    last_page: number;
    per_page: number;
    total: number;
    links?: TablePaginationLink[];
};

/**
 * Whether a list needs its pagination footer: more than one page, or enough
 * rows that a smaller / larger "Rows per page" choice changes what is shown.
 *
 * @param pagination - Current paginator state
 * @returns `true` when {@link TablePaginationFooter} has something to render
 */
export function hasTablePaginationFooter(
    pagination: TablePaginationState,
): boolean {
    return (
        pagination.last_page > 1 || pagination.total > LIST_PER_PAGE_OPTIONS[0]
    );
}

/**
 * Admin list footer in three areas: the row range ("1–20 of 312") on the
 * left, the page links centred, and the shared rows-per-page select ("20 /
 * page"; 10 / 20 / 50 / 100, URL `per_page`, resets to page 1 and keeps every
 * other query param) on the right. Default-size (32px) shadcn Select per the control scale.
 *
 * @param props.pagination - Current paginator state
 * @returns {JSX.Element}
 */
export function TablePaginationFooter({
    pagination,
}: {
    pagination: TablePaginationState;
}) {
    const { t } = useTranslation();
    const firstRow = Math.min(
        (pagination.current_page - 1) * pagination.per_page + 1,
        pagination.total,
    );
    const lastRow = Math.min(
        pagination.current_page * pagination.per_page,
        pagination.total,
    );

    return (
        <div className="flex w-full flex-wrap items-center justify-between gap-x-6 gap-y-3 sm:grid sm:grid-cols-[1fr_auto_1fr]">
            <p
                className="text-sm whitespace-nowrap text-muted-foreground tabular-nums"
                data-test="pagination-range"
            >
                {t('common.pageRange', {
                    from: firstRow,
                    to: lastRow,
                    total: pagination.total,
                })}
            </p>
            {pagination.last_page > 1 ? (
                <TablePagination
                    links={pagination.links ?? []}
                    className="mx-0 w-auto sm:col-start-2"
                />
            ) : null}
            <div className="sm:col-start-3 sm:justify-self-end">
                <Select
                    value={String(pagination.per_page)}
                    onValueChange={(value) =>
                        router.get(
                            listUrlWithPerPage(
                                window.location.href,
                                Number(value),
                            ),
                            {},
                            { preserveScroll: true },
                        )
                    }
                >
                    <SelectTrigger
                        aria-label={t('common.rowsPerPage')}
                        className="w-auto"
                        data-test="rows-per-page"
                    >
                        <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                        {LIST_PER_PAGE_OPTIONS.map((option) => (
                            <SelectItem key={option} value={String(option)}>
                                {t('common.perPageOption', {
                                    count: option,
                                })}
                            </SelectItem>
                        ))}
                    </SelectContent>
                </Select>
            </div>
        </div>
    );
}

/** "Rows per page" choices for admin lists (antd set; mirrors ValidatesListPerPageTrait). */
export const LIST_PER_PAGE_OPTIONS = [10, 20, 50, 100] as const;

/** Server default page size when `per_page` is absent or unsupported. */
export const DEFAULT_LIST_PER_PAGE = 20;

/**
 * `per_page` query value to keep when a list rebuilds its URL (search, sort,
 * filters): the current size, or `undefined` for the default so URLs stay clean.
 *
 * @param perPage - Current page size from the paginator props
 * @returns Value for the `per_page` query param
 */
export function listPerPageQuery(
    perPage: number | undefined,
): number | undefined {
    return perPage && perPage !== DEFAULT_LIST_PER_PAGE ? perPage : undefined;
}

/**
 * Current URL with a new `per_page` (dropped when default) and `page` reset to 1.
 * Every other query param (search, sort, filters, trashed) is kept.
 *
 * @param currentUrl - Absolute or relative URL of the list page
 * @param perPage - Selected page size
 * @returns Relative URL (path + query) to visit
 */
export function listUrlWithPerPage(
    currentUrl: string,
    perPage: number,
): string {
    const url = new URL(currentUrl, window.location.origin);
    url.searchParams.delete('page');

    if (perPage === DEFAULT_LIST_PER_PAGE) {
        url.searchParams.delete('per_page');
    } else {
        url.searchParams.set('per_page', String(perPage));
    }

    return `${url.pathname}${url.search}`;
}
